class Solution {
    int gcd(int a, int b) {
        while (b) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
public:
    int minOperations(vector<int>& nums, vector<int>& numsDivide) {
        int g = numsDivide[0];
        for (int i = 1; i < (int)numsDivide.size(); i++) {
            g = gcd(g, numsDivide[i]);
            if (g == 1) break;
        }

        int minValid = INT_MAX;
        for (int x : nums) {
            if (g % x == 0) {
                minValid = min(minValid, x);
            }
        }

        if (minValid == INT_MAX) return -1;

        int deletions = 0;
        for (int x : nums) {
            if (x < minValid) deletions++;
        }

        return deletions;
    }
};
